text:
{
  "fill": [
    {
      "prompt": "瀏覽器判斷兩個網頁是否同源時，會比較協定、主機和 ___。",
      "answers": [
        [
          "埠號",
          "端口號"
        ]
      ]
    },
    {
      "prompt": "協定、主機、埠號三者必須 ___ 才算同源。",
      "answers": [
        [
          "完全相同"
        ]
      ]
    },
    {
      "prompt": "把同一主機的網址從 https 換成 http，兩個來源就會變成 ___；即使主機相同，換一個埠號也會有相同結果。",
      "answers": [
        [
          "不同源"
        ]
      ]
    }
  ],
  "apply": [
    {
      "prompt": "某網頁想讀取同一主機下另一個不同路徑的資料。根據同源政策，這兩個頁面是否同源？請說明判斷理由。",
      "rubric": [
        "是否指出兩個頁面位於同一主機",
        "是否指出只有路徑不同不會造成不同源",
        "是否判斷兩個頁面同源"
      ]
    },
    {
      "prompt": "某網頁要讀取銀行網站的回應，但兩者的主機相同、埠號相同，協定卻分別是 https 和 http。根據同源政策，這個讀取是否會被視為同源？請說明理由。",
      "rubric": [
        "是否指出兩個網址的協定不同",
        "是否判斷兩個來源不同源",
        "是否指出來源必須包含協定、主機、埠號三者完全相同"
      ]
    }
  ]
}
